DO $$ DECLARE def text; BEGIN
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='submit_pdv_operator_with_contact'; def=replace(def,'AND request->>''type''<>''Delivery'' THEN','AND (request->>''type''<>''Delivery'' OR phone_digits<>'''') THEN'); def=replace(def,'SELECT data INTO snapshot FROM public.pdv_state WHERE id=1;','IF request->>''type''=''Delivery'' AND phone_digits='''' AND contact_id IS NOT NULL THEN INSERT INTO public.pdv_customer_visits(order_id,customer_id,seller_id) VALUES(request->>''id'',contact_id,auth.uid()); END IF; SELECT data INTO snapshot FROM public.pdv_state WHERE id=1;'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='save_delivery_route'; def=replace(def,'rid=coalesce(route_id,gen_random_uuid());','PERFORM public.validate_delivery_input(jsonb_build_object(''address'',d.address)) FROM public.delivery_orders d WHERE d.id=ANY(stops); rid=coalesce(route_id,gen_random_uuid());'); EXECUTE def;
END $$;